extern "C" int ds4_gpu_glm_k_b_project_typed_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *kv_norm,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              weight_type,
        uint32_t              n_tokens,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              n_head) {
    fprintf(stderr, "ds4: CUDA stub called: ds4_gpu_glm_k_b_project_typed_tensor\n");
    return 0;
}

__global__ static void glm_kv_lora_rms_norm_kernel(
        float *dst,
        const float *src,
        const float *w,
        uint32_t n_tokens,
        uint32_t kv_raw_dim,
        uint32_t kv_lora_dim,
        float eps) {
    const uint32_t row = blockIdx.x;
    if (row >= n_tokens) return;
    const uint32_t tid = threadIdx.x;
    const uint32_t nth = blockDim.x;
    const float *x = src + (uint64_t)row * kv_raw_dim;
    float *out = dst + (uint64_t)row * kv_lora_dim;
    __shared__ float scratch[256];
    float ss = 0.0f;
    for (uint32_t i = tid; i < kv_lora_dim; i += nth) {
        const float v = x[i];
        ss += v * v;
    }
    scratch[tid] = ss;
    __syncthreads();
    for (uint32_t step = nth >> 1; step > 0; step >>= 1) {
        if (tid < step) scratch[tid] += scratch[tid + step];
        __syncthreads();
    }
    const float inv = rsqrtf(scratch[0] / (float)kv_lora_dim + eps);
    for (uint32_t i = tid; i < kv_lora_dim; i += nth) {
        out[i] = x[i] * inv * w[i];
    }
}

extern "C" int ds4_gpu_glm_kv_lora_rms_norm_tensor(
        ds4_gpu_tensor       *dst,
        const ds4_gpu_tensor *src,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              n_tokens,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        float                 eps) {
    if (!dst || !src || !model_map || n_tokens == 0 ||
        kv_lora_dim == 0 || kv_lora_dim > kv_raw_dim) {
        return 0;
    }
    const uint64_t wb = (uint64_t)kv_lora_dim * sizeof(float);
    if (weight_offset > model_size || wb > model_size - weight_offset ||
        src->bytes < (uint64_t)n_tokens * kv_raw_dim * sizeof(float) ||
        dst->bytes < (uint64_t)n_tokens * kv_lora_dim * sizeof(float)) {
        return 0;
    }
    const int logical_tier = cuda_current_tier();
    const float *w = (const float *)cuda_resolve_weight_ptr(
            model_map, weight_offset, wb, logical_tier, "glm_kv_lora_norm");
    if (!w) return 0;
    glm_kv_lora_rms_norm_kernel<<<n_tokens, 256>>>(
            (float *)dst->ptr, (const float *)src->ptr, w,
            n_tokens, kv_raw_dim, kv_lora_dim, eps);
    return cuda_ok(cudaGetLastError(), "glm kv lora rms norm launch");
}



__global__ static void glm_qk_lowrank_q8_0_batch_kernel(
        float *qk_low,
        const char *weight,
        const float *q,
        uint32_t n_tokens,
        uint32_t n_head,
        uint32_t kv_lora_dim,
        uint32_t qk_nope,
        uint32_t qk_dim,
        uint64_t row_bytes) {
    const uint32_t head = blockIdx.x;
    const uint32_t token = blockIdx.y;
    if (head >= n_head || token >= n_tokens) return;
    const uint32_t tid = threadIdx.x;
    const uint32_t nth = blockDim.x;
    const float *qh = q + (uint64_t)token * n_head * qk_dim +
                      (uint64_t)head * qk_dim;
    float *out = qk_low + (uint64_t)token * n_head * kv_lora_dim +
                 (uint64_t)head * kv_lora_dim;
    for (uint32_t j = tid; j < kv_lora_dim; j += nth) {
        const char *row = weight +
            ((uint64_t)head * kv_lora_dim + j) * row_bytes;
        out[j] = glm_q8_0_dot_row_dev(row, qh, qk_nope);
    }
}

extern "C" int ds4_gpu_glm_qk_lowrank_typed_batch_tensor(
        ds4_gpu_tensor       *qk_low,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              weight_type,
        uint32_t              n_tokens,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_dim) {
    if (!qk_low || !q || !model_map || n_tokens == 0 || n_head == 0 ||
        kv_lora_dim == 0 || qk_nope == 0 || (qk_nope & 31u) != 0u) {
        return 0;
    }
    if (weight_type != 8u) {
        fprintf(stderr, "ds4: glm qk_lowrank: unsupported type %u\n",
                weight_type);
        return 0;
    }
    const uint64_t row_bytes = ((uint64_t)qk_nope / 32u) * 34u;
    const uint64_t wbytes = (uint64_t)n_head * kv_lora_dim * row_bytes;
    if (weight_offset > model_size || wbytes > model_size - weight_offset ||
        q->bytes < (uint64_t)n_tokens * n_head * qk_dim * sizeof(float) ||
        qk_low->bytes <
            (uint64_t)n_tokens * n_head * kv_lora_dim * sizeof(float)) {
        return 0;
    }
    const int logical_tier = cuda_current_tier();
    const char *w = (const char *)cuda_resolve_weight_ptr(
            model_map, weight_offset, wbytes, logical_tier, "glm_k_b_qk");
    if (!w) return 0;
    if (g_q8_dequant_gemm_enabled && g_cublas_ready && n_tokens >= 128u) {
        /* Per-head strided-batched GEMM over a dequantized k_b: the
         * per-(token,head) warp kernel was ~65ms/layer at 820 tokens.
         * Scratch (executing device): [w_f16][q_f16][out_f32]. */
        const uint64_t wh_bytes =
            (uint64_t)n_head * kv_lora_dim * qk_nope * sizeof(__half);
        const uint64_t xh_off = (wh_bytes + 255u) & ~255ull;
        const uint64_t xh_bytes =
            (uint64_t)n_tokens * n_head * qk_dim * sizeof(__half);
        const uint64_t oo_off = (xh_off + xh_bytes + 255u) & ~255ull;
        const uint64_t oo_bytes =
            (uint64_t)n_tokens * n_head * kv_lora_dim * sizeof(float);
        void *tmp = cuda_tmp_alloc_on(logical_tier, oo_off + oo_bytes,
                                      "glm qk_low gemm");
        if (tmp) {
            __half *wh = (__half *)tmp;
            __half *xh = (__half *)((char *)tmp + xh_off);
            float *oo = (float *)((char *)tmp + oo_off);
            const uint64_t total_blocks =
                (uint64_t)n_head * kv_lora_dim * (qk_nope / 32u);
            q8_0_dequant_f16_kernel<<<(unsigned)((total_blocks * 2u + 255u) / 256u), 256>>>(
                    wh, (const unsigned char *)w, total_blocks,
                    qk_nope / 32u, qk_nope);
            const uint64_t xn = (uint64_t)n_tokens * n_head * qk_dim;
            f32_to_f16_kernel<<<(xn + 255u) / 256u, 256>>>(
                    xh, (const float *)q->ptr, xn);
            if (cuda_ok(cudaGetLastError(), "glm qk_low gemm staging")) {
                const float alpha = 1.0f;
                const float beta = 0.0f;
                cublasStatus_t st = cublasGemmStridedBatchedEx(
                        cuda_cublas_for_tier(logical_tier),
                        CUBLAS_OP_T, CUBLAS_OP_N,
                        (int)kv_lora_dim, (int)n_tokens, (int)qk_nope,
                        &alpha,
                        wh, CUDA_R_16F, (int)qk_nope,
                        (long long)((uint64_t)kv_lora_dim * qk_nope),
                        xh, CUDA_R_16F, (int)(n_head * qk_dim),
                        (long long)qk_dim,
                        &beta,
                        oo, CUDA_R_32F, (int)(n_head * kv_lora_dim),
                        (long long)kv_lora_dim,
                        (int)n_head,
                        CUDA_R_32F, CUBLAS_GEMM_DEFAULT);
                if (st == CUBLAS_STATUS_SUCCESS &&
                    cuda_ok(cudaMemcpyAsync(qk_low->ptr, oo, oo_bytes,
                            cudaMemcpyDeviceToDevice, 0),
                            "glm qk_low gemm out copy")) {
                    return 1;
                }
                fprintf(stderr,
                        "ds4: glm qk_low gemm failed (status %d); native path\n",
                        (int)st);
            }
        }
    }
    dim3 grid(n_head, n_tokens, 1);
    glm_qk_lowrank_q8_0_batch_kernel<<<grid, 128>>>(
            (float *)qk_low->ptr, w, (const float *)q->ptr,
            n_tokens, n_head, kv_lora_dim, qk_nope, qk_dim, row_bytes);
    return cuda_ok(cudaGetLastError(), "glm qk lowrank batch launch");
}

extern "C" int ds4_gpu_glm_qk_lowrank_typed_tensor(
        ds4_gpu_tensor       *qk_low,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              weight_type,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_dim) {
    return ds4_gpu_glm_qk_lowrank_typed_batch_tensor(qk_low, q, model_map,
                                                     model_size,
                                                     weight_offset,
                                                     weight_type, 1u, n_head,
                                                     kv_lora_dim, qk_nope,
                                                     qk_dim);
}

/* Fused decode-path QKV norm + compact-KV store, one block per
 * (token, part): part 0 rms-norms q into q_out, part 1 rms-norms
 * kv_raw[:kv_lora_dim] into the kv_lora ring, part 2 copies the
 * UNROTATED rope tail into the k_rope ring (roped at attention read). */
__global__ static void glm_qkv_norm_store_compact_kv_kernel(
        float *q_dst,
        const float *q_src,
        const float *q_w,
        uint32_t q_n,
        const float *kv_raw,
        const float *kv_w,
        char *kv_lora_cache,
        char *k_rope_cache,
        uint32_t pos0,
        uint32_t cache_cap,
        uint32_t kv_raw_dim,
        uint32_t kv_lora_dim,
        uint32_t qk_rope,
        int cache_f16,
        float eps) {
    const uint32_t token = blockIdx.x;
    const uint32_t part = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    const uint32_t nth = blockDim.x;
    const uint32_t pos = pos0 + token;

    if (part == 2u) {
        if (pos >= cache_cap) return;
        const float *src = kv_raw + (uint64_t)token * kv_raw_dim + kv_lora_dim;
        if (cache_f16) {
            __half *dst = (__half *)k_rope_cache + (uint64_t)pos * qk_rope;
            for (uint32_t i = tid; i < qk_rope; i += nth) {
                dst[i] = __float2half(src[i]);
            }
        } else {
            float *dst = (float *)k_rope_cache + (uint64_t)pos * qk_rope;
            for (uint32_t i = tid; i < qk_rope; i += nth) {
                dst[i] = src[i];
            }
        }
        return;
    }

    const bool kv_task = part != 0u;
    const uint32_t n = kv_task ? kv_lora_dim : q_n;
    const float *x = kv_task ? kv_raw + (uint64_t)token * kv_raw_dim
                             : q_src + (uint64_t)token * q_n;
    const float *w = kv_task ? kv_w : q_w;

    __shared__ float sh[32];
    float sumf = 0.0f;
    for (uint32_t i = tid; i < n; i += nth) {
        const float v = x[i];
        sumf += v * v;
    }
    for (int off = 16; off > 0; off >>= 1) {
        sumf += __shfl_xor_sync(0xffffffffu, sumf, off);
    }
    if ((tid & 31u) == 0u) sh[tid >> 5] = sumf;
    __syncthreads();
    if (tid < 32u) {
        sumf = (tid < (nth + 31u) / 32u) ? sh[tid] : 0.0f;
        for (int off = 16; off > 0; off >>= 1) {
            sumf += __shfl_xor_sync(0xffffffffu, sumf, off);
        }
        if (tid == 0u) sh[0] = sumf;
    }
    __syncthreads();
    const float scale = rsqrtf(sh[0] / (float)n + eps);

    if (!kv_task) {
        float *y = q_dst + (uint64_t)token * q_n;
        for (uint32_t i = tid; i < n; i += nth) {
            y[i] = (x[i] * scale) * w[i];
        }
        return;
    }

    if (pos >= cache_cap) return;
    if (cache_f16) {
        __half *dst = (__half *)kv_lora_cache + (uint64_t)pos * kv_lora_dim;
        for (uint32_t i = tid; i < kv_lora_dim; i += nth) {
            dst[i] = __float2half((x[i] * scale) * w[i]);
        }
    } else {
        float *dst = (float *)kv_lora_cache + (uint64_t)pos * kv_lora_dim;
        for (uint32_t i = tid; i < kv_lora_dim; i += nth) {
            dst[i] = (x[i] * scale) * w[i];
        }
    }
}

extern "C" int ds4_gpu_glm_qkv_norm_store_compact_kv_tensor(
        ds4_gpu_tensor       *q_out,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              q_weight_offset,
        uint32_t              q_n,
        ds4_gpu_tensor       *kv_lora_cache,
        ds4_gpu_tensor       *k_rope_cache,
        const ds4_gpu_tensor *kv_raw,
        uint64_t              kv_weight_offset,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_rope,
        bool                  cache_f16,
        float                 eps) {
    if (!q_out || !q || !kv_lora_cache || !k_rope_cache || !kv_raw ||
        !model_map || n_tokens == 0 || q_n == 0 || kv_lora_dim == 0 ||
        qk_rope == 0 || kv_raw_dim < kv_lora_dim + qk_rope ||
        q->bytes < (uint64_t)n_tokens * q_n * sizeof(float) ||
        q_out->bytes < (uint64_t)n_tokens * q_n * sizeof(float) ||
        kv_raw->bytes < (uint64_t)n_tokens * kv_raw_dim * sizeof(float)) {
        return 0;
    }
    if (q_weight_offset > model_size ||
        (uint64_t)q_n * sizeof(float) > model_size - q_weight_offset ||
        kv_weight_offset > model_size ||
        (uint64_t)kv_lora_dim * sizeof(float) > model_size - kv_weight_offset) {
        return 0;
    }
    const int logical_tier = cuda_current_tier();
    const float *q_w = (const float *)cuda_resolve_weight_ptr(
            model_map, q_weight_offset, (uint64_t)q_n * sizeof(float),
            logical_tier, "glm_q_norm");
    const float *kv_w = (const float *)cuda_resolve_weight_ptr(
            model_map, kv_weight_offset,
            (uint64_t)kv_lora_dim * sizeof(float),
            logical_tier, "glm_kv_norm");
    if (!q_w || !kv_w) return 0;
    dim3 grid(n_tokens, 3, 1);
    glm_qkv_norm_store_compact_kv_kernel<<<grid, 256>>>(
            (float *)q_out->ptr,
            (const float *)q->ptr,
            q_w,
            q_n,
            (const float *)kv_raw->ptr,
            kv_w,
            (char *)kv_lora_cache->ptr,
            (char *)k_rope_cache->ptr,
            pos0, cache_cap, kv_raw_dim, kv_lora_dim, qk_rope,
            cache_f16 ? 1 : 0, eps);
    return cuda_ok(cudaGetLastError(), "glm qkv norm store compact kv");
}

/* In-place interleaved-pair yarn rope on a [n_tokens][n_head][head_dim]
 * f32 tensor, rotating rot_dim dims starting at rot_offset. Shared by the
 * attention q tail (offset = head_dim - rot_dim) and the DSA indexer
 * (offset = 0). Grid (n_head, n_tokens). */
__global__ static void glm_rope_tail_offset_kernel(
        float *x,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t rot_dim,
        uint32_t rot_offset,
        uint32_t pos0,
        uint32_t n_ctx_orig,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow) {
    const uint32_t head = blockIdx.x;
    const uint32_t token = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    const uint32_t nth = blockDim.x;
    if (rot_dim == 0u || (rot_dim & 1u) != 0u ||
        rot_offset > head_dim || rot_dim > head_dim - rot_offset) return;

    const uint32_t pos = pos0 + token;
    float *row = x + ((uint64_t)token * n_head + head) * head_dim + rot_offset;

    float corr_dims[2] = {0.0f, 0.0f};
    if (ext_factor != 0.0f) {
        corr_dims[0] = fmaxf(0.0f,
            floorf(glm_rope_yarn_corr_factor_dev((int)rot_dim,
                    (int)n_ctx_orig, beta_fast, freq_base)));
        corr_dims[1] = fminf((float)rot_dim - 1.0f,
            ceilf(glm_rope_yarn_corr_factor_dev((int)rot_dim,
                    (int)n_ctx_orig, beta_slow, freq_base)));
    }
    const float theta_base = (float)pos;
    const float inv_ndims = -1.0f / (float)rot_dim;
    for (uint32_t i = tid * 2u; i < rot_dim; i += nth * 2u) {
        const float theta =
            theta_base * powf(freq_base, inv_ndims * (float)i);
        float ct, st;
        glm_rope_yarn_dev(theta, freq_scale, corr_dims, (int)i,
                          ext_factor, attn_factor, &ct, &st);
        const float x0 = row[i];
        const float x1 = row[i + 1u];
        row[i] = x0 * ct - x1 * st;
        row[i + 1u] = x0 * st + x1 * ct;
    }
}

static int glm_rope_tail_offset_launch(
        ds4_gpu_tensor *x,
        uint32_t n_tokens, uint32_t n_head, uint32_t head_dim,
        uint32_t rot_dim, uint32_t rot_offset, uint32_t pos0,
        uint32_t n_ctx_orig, float freq_base, float freq_scale,
        float ext_factor, float attn_factor,
        float beta_fast, float beta_slow, const char *what) {
    if (!x || n_tokens == 0 || n_head == 0 || head_dim == 0 ||
        rot_dim == 0 || (rot_dim & 1u) != 0u || rot_offset > head_dim ||
        rot_dim > head_dim - rot_offset ||
        x->bytes < (uint64_t)n_tokens * n_head * head_dim * sizeof(float)) {
        return 0;
    }
    dim3 grid(n_head, n_tokens, 1);
    glm_rope_tail_offset_kernel<<<grid, 32>>>(
            (float *)x->ptr, n_head, head_dim, rot_dim, rot_offset,
            pos0, n_ctx_orig, freq_base, freq_scale,
            ext_factor, attn_factor, beta_fast, beta_slow);
    return cuda_ok(cudaGetLastError(), what);
}

extern "C" int ds4_gpu_glm_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow) {
    if (rot_dim > head_dim) return 0;
    return glm_rope_tail_offset_launch(x, n_tokens, n_head, head_dim,
            rot_dim, head_dim - rot_dim, pos0, n_ctx_orig,
            freq_base, freq_scale, ext_factor, attn_factor,
            beta_fast, beta_slow, "glm rope tail");
}

extern "C" int ds4_gpu_glm_routed_moe_batch_direct_scalar_q4_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *mid,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                up_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                up_expert_bytes,
        uint64_t                up_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        uint32_t                layer_index,
        const ds4_gpu_tensor *x,
        uint32_t                n_tokens,
        uint32_t                mid_token_stride) {
    if (!out || !mid || !model_map || !selected || !weights || !x ||
        gate_type != 12u || up_type != 12u || down_type != 12u ||
        n_tokens == 0u || n_expert == 0u || n_total_expert == 0u ||
        mid_token_stride != n_expert * expert_mid_dim ||
        gate_expert_bytes != up_expert_bytes ||
        gate_row_bytes != up_row_bytes ||
        expert_in_dim == 0u || expert_mid_dim == 0u || out_dim == 0u) {
        return 0;
    }
    const int tier = ds4_tensor_device_idx(out);
    if (tier < 0 || tier >= DS4_MAX_GPUS || ds4_tensor_device_idx(mid) != tier ||
        ds4_tensor_device_idx(selected) != tier || ds4_tensor_device_idx(weights) != tier ||
        ds4_tensor_device_idx(x) != tier) return 0;
    const uint64_t gate_bytes = (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float);
    const uint64_t down_bytes = (uint64_t)n_tokens * n_expert * out_dim * sizeof(float);
    static ds4_gpu_tensor *gate_scratch[DS4_MAX_GPUS] = {0};
    static ds4_gpu_tensor *up_scratch[DS4_MAX_GPUS] = {0};
    static ds4_gpu_tensor *down_scratch[DS4_MAX_GPUS] = {0};
    if (!gate_scratch[tier] || gate_scratch[tier]->bytes < gate_bytes) {
        ds4_gpu_tensor_free(gate_scratch[tier]);
        gate_scratch[tier] = ds4_gpu_tensor_alloc_ptr_on(tier, gate_bytes);
    }
    if (!up_scratch[tier] || up_scratch[tier]->bytes < gate_bytes) {
        ds4_gpu_tensor_free(up_scratch[tier]);
        up_scratch[tier] = ds4_gpu_tensor_alloc_ptr_on(tier, gate_bytes);
    }
    if (!down_scratch[tier] || down_scratch[tier]->bytes < down_bytes) {
        ds4_gpu_tensor_free(down_scratch[tier]);
        down_scratch[tier] = ds4_gpu_tensor_alloc_ptr_on(tier, down_bytes);
    }
    if (!gate_scratch[tier] || !up_scratch[tier] || !down_scratch[tier]) return 0;
    return routed_moe_launch(out, gate_scratch[tier], up_scratch[tier], mid,
                             down_scratch[tier], model_map, model_size,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, n_total_expert, n_expert,
                             0.0f, x, layer_index, n_tokens, 0, 0);
}

/* Poolside's Q4_K MUL_MAT_ID changes activation quantization at its GB10
 * MMVQ/MMQ boundary.  The existing full-warp quantizer above covers MMVQ.
 * This kernel covers MMQ while retaining the ordinary 36-byte Q8_1 layout
 * consumed by the correctness-first resident kernels below.  Eight lanes
 * jointly quantize one 32-value group, matching Poolside's float4 load and
 * reciprocal-first arithmetic. */
__launch_bounds__(256, 1)
static __global__ void glm_poolside_q8_1_mmq_quantize_kernel(
        poolside_q8_1_block *out,
        const float *input,
        uint64_t group_count) {
    const uint32_t lane8 = threadIdx.x & 7u;
    const uint64_t group =
        (uint64_t)blockIdx.x * 32u + (threadIdx.x >> 3u);
    if (group >= group_count) return;

    const float4 values = ((const float4 *)(input + group * 32u))[lane8];
    float amax = fabsf(values.x);
    amax = fmaxf(amax, fabsf(values.y));
    amax = fmaxf(amax, fabsf(values.z));
    amax = fmaxf(amax, fabsf(values.w));
    float sum = __fadd_rn(values.x, values.y);
    sum = __fadd_rn(sum, values.z);
    sum = __fadd_rn(sum, values.w);
    const uint32_t mask = __activemask();
#pragma unroll
    for (uint32_t offset = 4u; offset > 0u; offset >>= 1u) {
        amax = fmaxf(
            amax, __shfl_xor_sync(mask, amax, offset, 32));
        sum = __fadd_rn(
            sum, __shfl_xor_sync(mask, sum, offset, 32));
    }

    const float inverse_scale = amax == 0.0f ? 0.0f : 127.0f / amax;
    char4 quantized;
    quantized.x = (signed char)roundf(values.x * inverse_scale);
    quantized.y = (signed char)roundf(values.y * inverse_scale);
    quantized.z = (signed char)roundf(values.z * inverse_scale);
    quantized.w = (signed char)roundf(values.w * inverse_scale);
    *(char4 *)(out[group].qs + lane8 * 4u) = quantized;
    if (lane8 == 0u) {
        const float scale = inverse_scale == 0.0f ? 0.0f :
            1.0f / inverse_scale;
        out[group].d = __float2half_rn(scale);
        out[group].s = __float2half_rn(sum);
    }
}

__device__ __forceinline__ static float
dev_dot_q4_K_q8_1_poolside_mmvq_fragment(
        const cuda_block_q4_K *weight,
        const poolside_q8_1_block *input,
        uint32_t iqs) {
    const uint32_t q8_offset = 2u * ((iqs / 2u) / 4u);
    const uint32_t chunk = (iqs / 2u) % 4u;
    const int32_t *q4 = (const int32_t *)(weight->qs +
        16u * q8_offset + 4u * chunk);
    const int32_t v0 = q4[0];
    const int32_t v1 = q4[4];

    const uint16_t *packed_scales =
        (const uint16_t *)weight->scales;
    uint16_t auxiliary[2];
    const uint32_t j = q8_offset / 2u;
    if (j < 2u) {
        auxiliary[0] = packed_scales[j] & 0x3f3fu;
        auxiliary[1] = packed_scales[j + 2u] & 0x3f3fu;
    } else {
        auxiliary[0] =
            ((packed_scales[j + 2u] >> 0u) & 0x0f0fu) |
            ((packed_scales[j - 2u] & 0xc0c0u) >> 2u);
        auxiliary[1] =
            ((packed_scales[j + 2u] >> 4u) & 0x0f0fu) |
            ((packed_scales[j] & 0xc0c0u) >> 2u);
    }
    const uint8_t *scales = (const uint8_t *)auxiliary;
    const uint8_t *minimums = scales + 2u;

    float scaled_sum = 0.0f;
    float minimum_sum = 0.0f;
#pragma unroll
    for (uint32_t i = 0; i < 2u; i++) {
        const int32_t q40 = (v0 >> (4u * i)) & 0x0f0f0f0f;
        const int32_t q41 = (v1 >> (4u * i)) & 0x0f0f0f0f;
        const int32_t *q8 =
            (const int32_t *)input[q8_offset + i].qs + chunk;
        const int32_t u0 = q8[0];
        const int32_t u1 = q8[4];
        const int32_t dot = __dp4a(q41, u1, __dp4a(q40, u0, 0));
        const int32_t q8_sum = __dp4a(
            0x01010101, u1, __dp4a(0x01010101, u0, 0));
        const float d8 = __half2float(input[q8_offset + i].d);
        scaled_sum += d8 * (dot * scales[i]);
        minimum_sum += d8 * (q8_sum * minimums[i]);
    }
    return dev_f16_to_f32(weight->d) * scaled_sum -
           dev_f16_to_f32(weight->dmin) * minimum_sum;
}

#ifdef DS4_TEST_HOOKS
__global__ static void f32_mmvf_poolside_microscope_kernel(
        float *value,
        const float *weight,
        const float *activation,
        uint32_t input_elements) {
    const uint32_t tid = threadIdx.x;
    const float2 *weight2 = (const float2 *)weight;
    const float2 *activation2 = (const float2 *)activation;
    const uint32_t input_pairs = input_elements / 2u;
    float sum = 0.0f;
    for (uint32_t col2 = tid; col2 < input_pairs; col2 += 256u) {
        const float2 w = weight2[col2];
        const float2 x = activation2[col2];
        sum += w.x * x.x;
        sum += w.y * x.y;
    }
#pragma unroll
    for (uint32_t offset = 16u; offset > 0u; offset >>= 1u) {
        sum += __shfl_xor_sync(0xffffffffu, sum, offset, 32);
    }

    extern __shared__ float warp_sums[];
    if (tid < 32u) warp_sums[tid] = 0.0f;
    __syncthreads();
    if ((tid & 31u) == 0u) warp_sums[tid / 32u] = sum;
    __syncthreads();
    if (tid < 32u) {
        sum = warp_sums[tid];
#pragma unroll
        for (uint32_t offset = 16u; offset > 0u; offset >>= 1u) {
            sum += __shfl_xor_sync(0xffffffffu, sum, offset, 32);
        }
        if (tid == 0u) value[0] = sum;
    }
}

extern "C" int ds4_gpu_test_f32_mmvf_microscope_tensor(
        ds4_gpu_tensor *values,
        const ds4_gpu_tensor *weight_row,
        const ds4_gpu_tensor *activation,
        uint32_t input_elements) {
    if (!values || !weight_row || !activation ||
        !values->ptr || !weight_row->ptr || !activation->ptr ||
        input_elements == 0u || (input_elements & 1u) != 0u ||
        values->bytes < 2u * sizeof(float) ||
        weight_row->bytes < (uint64_t)input_elements * sizeof(float) ||
        activation->bytes < (uint64_t)input_elements * sizeof(float)) {
        return 0;
    }
    const int tier = ds4_tensor_device_idx(values);
    if (tier < 0 || tier >= g_n_gpus ||
        ds4_tensor_device_idx(weight_row) != tier ||
        ds4_tensor_device_idx(activation) != tier) {
        return 0;
    }
    int current_device = -1;
    if (!cuda_ok(cudaGetDevice(&current_device),
                 "F32 MMVF microscope get device") ||
        current_device != g_gpu[tier].device_id) {
        return 0;
    }
    matmul_f32_kernel<<<1, 256>>>(
        (float *)values->ptr,
        (const float *)weight_row->ptr,
        (const float *)activation->ptr,
        input_elements, 1u, 1u);
    if (!cuda_ok(cudaGetLastError(),
                 "F32 MMVF microscope serial launch")) {
        return 0;
    }
    f32_mmvf_poolside_microscope_kernel<<<1, 256, 32u * sizeof(float)>>>(
        (float *)values->ptr + 1u,
        (const float *)weight_row->ptr,
        (const float *)activation->ptr,
        input_elements);
    return cuda_ok(cudaGetLastError(),
                   "F32 MMVF microscope Poolside launch");
}

__global__ static void q4_k_mmvq_serial_microscope_kernel(
        float *values,
        const cuda_block_q4_K *weight_row,
        const poolside_q8_1_block *input,
        uint32_t q4_blocks) {
    if (blockIdx.x != 0u || threadIdx.x != 0u) return;
    float result = 0.0f;
    for (uint32_t block = 0; block < q4_blocks; block++) {
        result = __fadd_rn(
            result,
            dev_dot_q4_K_q8_1_mmvq_block(
                weight_row + block, input + (uint64_t)block * 8u));
    }
    values[0] = result;
}

__global__ static void q4_k_mmvq_poolside_microscope_kernel(
        float *values,
        const cuda_block_q4_K *weight_row,
        const poolside_q8_1_block *input,
        uint32_t q4_blocks) {
    const uint32_t lane = threadIdx.x;
    const uint32_t warp = threadIdx.y;
    const uint32_t tid = warp * 32u + lane;
    float partial = 0.0f;
    for (uint32_t block = tid / 16u;
         block < q4_blocks;
         block += 8u) {
        partial += dev_dot_q4_K_q8_1_poolside_mmvq_fragment(
            weight_row + block,
            input + (uint64_t)block * 8u,
            2u * (tid % 16u));
    }
    values[2u + tid] = partial;

    __shared__ float other_warps[3][32];
    if (warp > 0u) other_warps[warp - 1u][lane] = partial;
    __syncthreads();
    if (warp > 0u) return;
    partial += other_warps[0][lane];
    partial += other_warps[1][lane];
    partial += other_warps[2][lane];
#pragma unroll
    for (uint32_t offset = 16u; offset > 0u; offset >>= 1u) {
        partial += __shfl_xor_sync(0xffffffffu, partial, offset, 32);
    }
    if (lane == 0u) values[1] = partial;
}

extern "C" int ds4_gpu_test_q4_k_mmvq_microscope_tensor(
        ds4_gpu_tensor *values,
        ds4_gpu_tensor *quantized_input,
        const ds4_gpu_tensor *weight_row,
        const ds4_gpu_tensor *activation,
        uint32_t input_elements) {
    if (!values || !quantized_input || !weight_row || !activation ||
        !values->ptr || !quantized_input->ptr || !weight_row->ptr ||
        !activation->ptr || input_elements == 0u ||
        (input_elements & 255u) != 0u) {
        return 0;
    }
    const uint32_t q4_blocks = input_elements / 256u;
    const uint32_t q8_blocks = input_elements / 32u;
    const uint64_t row_bytes =
        (uint64_t)q4_blocks * sizeof(cuda_block_q4_K);
    const uint64_t q8_bytes =
        (uint64_t)q8_blocks * sizeof(poolside_q8_1_block);
    if (values->bytes < 130u * sizeof(float) ||
        quantized_input->bytes < q8_bytes ||
        weight_row->bytes < row_bytes ||
        activation->bytes < (uint64_t)input_elements * sizeof(float)) {
        return 0;
    }
    const int tier = ds4_tensor_device_idx(values);
    if (tier < 0 || tier >= g_n_gpus ||
        ds4_tensor_device_idx(quantized_input) != tier ||
        ds4_tensor_device_idx(weight_row) != tier ||
        ds4_tensor_device_idx(activation) != tier) {
        return 0;
    }
    int current_device = -1;
    if (!cuda_ok(cudaGetDevice(&current_device),
                 "Q4_K MMVQ microscope get device") ||
        current_device != g_gpu[tier].device_id) {
        return 0;
    }
    quantize_poolside_q8_1_f32_kernel<<<
        (input_elements + 255u) / 256u, 256>>>(
            (poolside_q8_1_block *)quantized_input->ptr,
            (const float *)activation->ptr,
            input_elements);
    if (!cuda_ok(cudaGetLastError(),
                 "Q4_K MMVQ microscope quantize")) {
        return 0;
    }
    q4_k_mmvq_serial_microscope_kernel<<<1, 1>>>(
        (float *)values->ptr,
        (const cuda_block_q4_K *)weight_row->ptr,
        (const poolside_q8_1_block *)quantized_input->ptr,
        q4_blocks);
    if (!cuda_ok(cudaGetLastError(),
                 "Q4_K MMVQ serial microscope")) {
        return 0;
    }
    q4_k_mmvq_poolside_microscope_kernel<<<1, dim3(32, 4, 1)>>>(
        (float *)values->ptr,
        (const cuda_block_q4_K *)weight_row->ptr,
        (const poolside_q8_1_block *)quantized_input->ptr,
        q4_blocks);
    return cuda_ok(cudaGetLastError(),
                   "Q4_K MMVQ Poolside microscope");
}

__global__ static void glm_poolside_q4_mmq_gate_up_test_kernel(
        float *out,
        const cuda_block_q4_K *gate_row,
        const cuda_block_q4_K *up_row,
        const poolside_q8_1_block *input_q8,
        uint32_t q4_blocks) {
    if (blockIdx.x != 0u || threadIdx.x != 0u) return;
    const float gate = dev_dot_q4_K_q8_1_mma_row(
        gate_row, input_q8, q4_blocks);
    const float up = dev_dot_q4_K_q8_1_mma_row(
        up_row, input_q8, q4_blocks);
    out[0] = gate;
    out[1] = up;
    out[2] = __fmul_rn(gate / (1.0f + expf(-gate)), up);
}

