extern "C" int ds4_gpu_matmul_quant_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                weight_type,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                n_tok) {
    switch (weight_type) {
    case 8u:   /* Q8_0 */
        return ds4_gpu_matmul_q8_0_tensor(out, model_map, model_size,
                                          weight_offset, in_dim, out_dim,
                                          x, n_tok);
    case 1u:   /* F16 */
        return ds4_gpu_matmul_f16_tensor(out, model_map, model_size,
                                         weight_offset, in_dim, out_dim,
                                         x, n_tok);
    default:
        fprintf(stderr, "ds4: matmul_quant: unsupported type %u\n",
                weight_type);
        return 0;
    }
}

extern "C" uint64_t ds4_gpu_recommended_working_set_size(void) {
    /* GLM graph memory guard: on this backend the model weights are
     * distributed across all devices by the multi-tier placement, so the
     * relevant budget is the aggregate VRAM. */
    int n = 0;
    if (cudaGetDeviceCount(&n) != cudaSuccess || n <= 0) return 0;
    size_t free_b = 0, total_b = 0;
    if (cudaMemGetInfo(&free_b, &total_b) != cudaSuccess) return 0;
    return (uint64_t)total_b * (uint64_t)n;
}

extern "C" uint64_t ds4_gpu_default_device_working_set_size(
        uint32_t *visible_devices_out) {
    if (visible_devices_out) *visible_devices_out = 0;

    int visible = 0;
    if (cudaGetDeviceCount(&visible) != cudaSuccess || visible <= 0) {
        (void)cudaGetLastError();
        return 0;
    }

    int previous = -1;
    if (cudaGetDevice(&previous) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    if (cudaSetDevice(0) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    size_t free_b = 0;
    size_t total_b = 0;
    const cudaError_t query_rc = cudaMemGetInfo(&free_b, &total_b);
    const cudaError_t restore_rc =
        previous == 0 ? cudaSuccess : cudaSetDevice(previous);
    if (query_rc != cudaSuccess || restore_rc != cudaSuccess || total_b == 0) {
        (void)cudaGetLastError();
        return 0;
    }

    (void)free_b;
    if (visible_devices_out) *visible_devices_out = (uint32_t)visible;
    return (uint64_t)total_b;
}

